package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.SecretDigester;

class RegistrationAccessTokenVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property registration access token of oauth client ")
  void test_registration_access_token_v_o_builder() {
    SecretDigester service = Mockito.mock(SecretDigester.class);
    Mockito.when(service.digest("small")).thenReturn("hmac-sha256:p0:example");
    Assertions.assertEquals("hmac-sha256:p0:example", RegistrationAccessTokenVO.fromPlain("small")
        .getRegistrationAccessTokenStored(service).orElse(null));
    Assertions.assertEquals("****", RegistrationAccessTokenVO.fromPlain("small").toString());
  }
}
